def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    cups = image_patch.find("cup")
    spoons = image_patch.find("spoon")
    if not cups or not spoons:
        return image_patch

    # Find the cup above a spoon on the right
    cups.sort(key=lambda c: c.vertical_center)
    spoons.sort(key=lambda s: s.horizontal_center)

    for cup in cups:
        for spoon in spoons:
            if cup.vertical_center < spoon.vertical_center and cup.horizontal_center > spoon.horizontal_center:
                return cup

    return cups[0]

